      SUBROUTINE CABD3(RC,TC,UC,RA,TA,UA,RB,TB,RBV,TBV,UBV)CC     COMPUTES RCV, TCV, AND UCV FROM PRELIMINARY CALCULATIONSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TMUL.CIN'      INCLUDE 'UMUL.CIN'CC     LOCAL VARIABLESC      INTEGER  I1, I2, I3, I4, I5, I6, I7      INTEGER  I234, INDA, INDB, INDEX3, I1MIN      REAL  DTR, DTT, S, URR, DURR, TR, TT      REAL  RA(6,6), RB(6,6), RBV(6,6), RC(6,6)      REAL  TA(5,21), TB(5,21), TBV(5,21), TC(5,21)      REAL  UA(5,56), UBV(5,56), UC(5,56)      REAL  UR(6), DUR(6)CC----------------------------------------------------------------------      CALL CABD2(RC,TC,RA,TA,RB,RBV,TBV)CC     PART OF UC FROM RA X UBVC      DO 20 I1 = 1, 5      DO 20 I234 = 1, 56      S = 0.0      DO 10 I5 = 1, 5      S = S + RA(I1,I5)*UBV(I5,I234)   10 CONTINUE      UC(I1,I234) = S   20 CONTINUECC     PART OF UC FROM UA X RB X RB X RBVC                   + UA X RB X RBB X RBC                   + UA X RBV X RB X RBC      IF (.NOT. UMUL) GO TO 300      DO 150 I1 = 1, 5      DO 150 I2 = 1, 6      INDA = 0      DO 150 I7 = 1, 6      DO 110 I6 = 1, I7      UR(I6) = 0.0      DUR(I6) = 0.0      DO 110 I5 = 1, I6      INDA = INDA + 1      UR(I6) = UR(I6) + UA(I1,INDA)*RB(I5,I2)      DUR(I6) = DUR(I6) + UA(I1,INDA)*RBV(I5,I2)   110 CONTINUEC      DO 140 I3 = 1, 6      URR = 0.0      DURR = 0.0      DO 120 I6 = 1, I7      URR = URR + UR(I6)*RB(I6,I3)      DURR = DURR + UR(I6)*RBV(I6,I3) + DUR(I6)*RB(I6,I3)  120 CONTINUE      IF (URR .EQ. 0.0 .AND. DURR .EQ. 0.0) GO TO 140C      DO 130 I4 = 1, 6      I234 = INDEX3(I2,I3,I4)      UC(I1,I234) = UC(I1,I234) + URR*RBV(I7,I4) + DURR*RB(I7,I4)  130 CONTINUE  140 CONTINUE  150 CONTINUECC     PART OF UC FROM TA X RBV X TBC                   + TA X RB X TBVC      IF (.NOT. TMUL) GO TO 300      I1MIN = 1      IF (.NOT. TMULT) I1MIN = 5C      DO 200 I1 = I1MIN, 5      DO 200 I2 = 1, 6      INDA = 0      DO 200 I6 = 1, 5      TR = 0.0      DTR = 0.0      DO 160 I5 = 1, I6      INDA = INDA + 1      TR = TR + TA(I1,INDA)*RB(I5,I2)      DTR = DTR + TA(I1,INDA)*RBV(I5,I2)  160 CONTINUEC      IF (TR .EQ. 0.0 .AND. DTR .EQ. 0.0) GO TO 200      INDB = 0      DO 170 I4 = 1, 6      DO 170 I3 = 1, I4      INDB = INDB + 1      I234 = INDEX3(I2,I3,I4)      UC(I1,I234) = UC(I1,I234) + TR*TBV(I6,INDB) + DTR*TB(I6,INDB)  170 CONTINUE  200 CONTINUECC     PART OF UC FROM TA X TBV X RBC                   + TA X TB X RBVC      DO 250 I1 = I1MIN, 5      INDB = 0      DO 250 I3 = 1, 6      DO 250 I2 = 1, I3      INDB = INDB + 1      INDA = 0      DO 250 I6 = 1, 6      TT = 0.0      DTT = 0.0      DO 210 I5 = 1, I6      INDA = INDA + 1      IF (I5 .EQ. 6) GO TO 210      TT = TT + TA(I1,INDA)*TB(I5,INDB)      DTT = DTT + TA(I1,INDA)*TBV(I5,INDB)  210 CONTINUEC      IF (TT .EQ. 0.0) GO TO 250      DO 220 I4 = 1, 6      I234 = INDEX3(I2,I3,I4)      UC(I1,I234) = UC(I1,I234) + TT*RBV(I6,I4) + DTT*RB(I6,I4)  220 CONTINUE  250 CONTINUEC  300 RETURN      END